package com.nettel.maritimo.next.work;
import android.app.*;import android.content.*;import android.os.Build;import androidx.core.app.NotificationCompat;import com.nettel.maritimo.next.R;import com.nettel.maritimo.next.data.Alert;import com.nettel.maritimo.next.ui.AlertsActivity;
public final class NotificationHelper {public static final String CHANNEL="maritime_alerts";public static void show(Context c,Alert a){NotificationManager m=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)m.createNotificationChannel(new NotificationChannel(CHANNEL,"Alertas marítimas",NotificationManager.IMPORTANCE_HIGH));Intent i=new Intent(c,AlertsActivity.class);PendingIntent p=PendingIntent.getActivity(c,a.id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new NotificationCompat.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_boat).setContentTitle(a.type+" · "+a.boat).setContentText(a.message).setStyle(new NotificationCompat.BigTextStyle().bigText(a.message)).setAutoCancel(true).setContentIntent(p).build();m.notify(a.id,n);} }
